import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable, of } from 'rxjs';
import { tap } from 'rxjs/operators';

export interface Korisnik {
  ime: string;
  prezime: string;
  email: string;
  lozinka: string;
  rola?: string;
}

@Injectable({
  providedIn: 'root'
})
export class AuthService {

  private baseUrl = 'http://localhost:8080/api/auth';

  constructor(private http: HttpClient) { }

  private jsonHeaders = {
    headers: new HttpHeaders({
      'Content-Type': 'application/json'
    }),
    withCredentials: true
  };

  register(korisnik: Korisnik): Observable<any> {
    return this.http.post(`${this.baseUrl}/register`, korisnik, this.jsonHeaders);
  }

  login(email: string, lozinka: string): Observable<any> {
    return this.http.post(`${this.baseUrl}/login`, { email, lozinka }, this.jsonHeaders);
  }

  logout(): Observable<void> {
    // Brišemo token lokalno i eventualno možemo pozvati backend da završi sesiju
    localStorage.removeItem('jwtToken');
    // Ako nema backend logout endpoint-a, samo vraćamo observable
    return of(void 0);
  }
}
